function saveUnit(id: string, dataHint?: string) {
  const participant = task.value.participants.find((item) => item.id === id)
  if (!participant) return
  const hint = dataHint ?? summarizeWorkbookForParticipant(participant)
  task.value = {
    ...task.value,
    participants: task.value.participants.map((item) => item.id === id
      ? { ...item, status: 'saved' as const, progress: 100, lastUpdate: '刚刚', dataHint: hint, blockers: [] }
      : item),
    progress: 0,
  }
  task.value.progress = Math.round(task.value.participants.reduce((sum, item) => sum + item.progress, 0) / task.value.participants.length)
  lastMessage.value = `「${participant.name}」已保存；工作表同源摘要：${hint}`
}

/** 工作表保存版本后：按油区/油田范围回写参与项，实现一级可见 */
function markScopeSaved(scopeKeys: string[], dataHint: string) {
  const keys = new Set(scopeKeys.filter(Boolean))
  if (!keys.size) return false
  let matched = false
  task.value = {
    ...task.value,
    participants: task.value.participants.map((item) => {
      if (!keys.has(item.area) && !keys.has(item.name)) return item
      matched = true
      return { ...item, status: 'saved' as const, progress: 100, lastUpdate: '刚刚', dataHint, blockers: [] }
    }),
  }
  if (matched) {
    task.value.progress = Math.round(task.value.participants.reduce((sum, item) => sum + item.progress, 0) / task.value.participants.length)
    lastMessage.value = `已同步工作表保存到任务参与项：${dataHint}`
  }
  return matched
}

function summarizeWorkbookForParticipant(participant: PlanningParticipant) {
  const wb = usePlanningWorkbookStore()
  const year = wb.years[0] ?? '2026'
  const rows = [...wb.rowsOf('oil'), ...wb.rowsOf('gas')].filter((row) => {
    if (participant.scope === '油田') return row.oilfield === participant.name || row.area === participant.area
    return row.area === participant.area || row.area === participant.name
  })
  const total = rows.reduce((sum, row) => sum + rowYearTotal(row, year), 0)
  return `${rows.length} 行 · ${year} 年合计 ${total.toFixed(1)}（来自规划工作表）`
}

