import { createPinia, setActivePinia } from 'pinia'
import { beforeEach, describe, expect, it } from 'vitest'
import { reserveRows } from '../src/mock/business'
import { buildSummaryFromReserveRows, useReserveSummaryStore } from '../src/stores/reserveSummary'
import { usePlanningTaskStore } from '../src/stores/planningTask'
import { usePlanningWorkbookStore } from '../src/stores/planningWorkbook'

describe('储量四表：由明细生成', () => {
  it('按油气田聚合地质储量与可采估算', () => {
    const rows = buildSummaryFromReserveRows(reserveRows)
    expect(rows.length).toBeGreaterThan(0)
    const field = reserveRows[0].oilfield
    const expectedGeo = Number(
      reserveRows
        .filter((item) => item.oilfield === field)
        .reduce((sum, item) => sum + item.internalLine, 0)
        .toFixed(1),
    )
    expect(rows.find((item) => item.field === field)?.geological).toBe(expectedGeo)
  })

  it('store 生成后标记来源与时间', () => {
    setActivePinia(createPinia())
    const store = useReserveSummaryStore()
    expect(store.hasGenerated).toBe(false)
    const count = store.generateFromRows(reserveRows, '单元测试')
    expect(count).toBe(store.rows.length)
    expect(store.hasGenerated).toBe(true)
    expect(store.sourceLabel).toBe('单元测试')
    expect(store.mockAlgorithm).toBe(true)
  })
})

describe('规划任务 ↔ 工作表同源', () => {
  beforeEach(() => {
    setActivePinia(createPinia())
  })

  it('saveUnit 写入来自工作表的 dataHint', () => {
    const taskStore = usePlanningTaskStore()
    usePlanningWorkbookStore()
    const target = taskStore.task.participants.find((item) => item.status === 'editing')
    expect(target).toBeTruthy()
    taskStore.saveUnit(target!.id)
    const saved = taskStore.task.participants.find((item) => item.id === target!.id)
    expect(saved?.status).toBe('saved')
    expect(saved?.dataHint).toContain('来自规划工作表')
  })

  it('markScopeSaved 按油区回写参与项', () => {
    const taskStore = usePlanningTaskStore()
    const matched = taskStore.markScopeSaved(['示例油区甲'], '工作表 V-test · 油 1 行')
    expect(matched).toBe(true)
    const participant = taskStore.task.participants.find((item) => item.area === '示例油区甲')
    expect(participant?.status).toBe('saved')
    expect(participant?.dataHint).toContain('工作表 V-test')
  })
})
